SELECT 'Family Homecare / FOMAG — Contrato de comodato', 'Contrato de comodato o préstamo de uso de Family Homecare para afiliados del FOMAG (5 páginas). Va con todos los préstamos de Family, junto con el F-FAM-11 del tipo de equipo.', $bloques$[{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":46}],"ancho_logo":20,"centro":[{"texto":"CONTRATO DE COMODATO\nO\nPRÉSTAMO DE USO","estilo":"titulo"}],"derecha":[{"etiqueta":"","valor":"01 DE MAYO DE 2024"},{"etiqueta":"ELABORADO POR:","valor":"VIERIZ LLANES"},{"etiqueta":"APROBADO POR:","valor":"RODOLFO RODRÍGUEZ"}],"logos_derecha":[{"texto":"{fiduprevisora}"},{"texto":"FOMAG"}],"pie":[{"etiqueta":"COD:","valor":"000"},{"etiqueta":"REVISION:","valor":"00"},{"etiqueta":"VERSION","valor":"01"},{"etiqueta":"Página","valor":"1 de 5"}]},{"tipo":"texto","tamano":11,"texto":"A los {{dia}} días del mes de {{mes}} de {{anio}}, en la ciudad de Valledupar, entre la SOCIEDAD **FAMILY HOMECARE S.A.S.**, persona jurídica de derecho privado, identificada con el Nit. 900830296-9, representada legalmente por el señor RODOLFO CARLOS RODRIGUEZ SHORBOGH, mayor de edad, residenciado en la ciudad de Valledupar, parte que se denominará **COMODANTE** y de otra parte el señor (a) {{recibe_nombre}}, identificado (a) con cédula de ciudadanía Nº {{recibe_documento}} en adelante se denominará **COMODATARIO**, celebran por medio de este documento **CONTRATO DE COMODATO** sobre los bienes que recibe el usuario por la prestación del servicio autorizado a la suscripción de este contrato y en las condiciones que a continuación se describen:\n\n**ANTECEDENTES**: Para la continuidad de la prestación del servicio de Salud en la población afiliada al FOMAG, la FIDUCIARIA LA PREVISORA S.A. VOCERA Y ADMINISTRADORA DE LOS RECURSOS DEL FOMAG acepto la manifestación de interés de esta sociedad, y nos envió contrato o documento denominado **\"ACUERDO DE VOLUNTADES COMO ACEPTACIÓN A LA MANIFESTACIÓN DE INTERÉS PARA LA CONFORMACIÓN DE LA RED DE PROVEEDORES PARA PRESTAR LOS SERVICIOS Y TECNOLOGÍAS EN SALUD PARA EL FOMAG \"** -FIDECOMISOS PATRIMONIOS AUTONOMOS FIDUCIARIA LA PREVISORA S.A. , con domicilio en la ciudad de BOGOTA D.C y FAMILY HOMECARE S.A.S., para la atención domiciliaria de sus afiliados acorde a las autorizaciones enviadas, asumiendo el pago por el servicio. FAMILY HOMECARE S.A.S. entrega los equipos autorizados a título gratuito a sus afiliados, para su uso, el equipo puede ser propio o alquilado, pero la persona que recibe o el beneficiario está obligado a cuidar el equipo y devolverlo cuando ha cumplido su finalidad. Acorde a lo anterior las partes se reúnen para celebrar el presente contrato con las siguientes clausulas:\n\n**PRIMERA. OBJETO.** El **COMODANTE** entrega al **COMODATARIO**, y éste recibe, a título de comodato, (préstamo de uso) los bienes que a continuación se describen:"},{"tipo":"tabla","fuente":"equipos","agrupar":"tipo","titulo":"EQUIPOS ENTREGADOS","accesorios":[{"etiqueta":"HUMIDIFICADOR"},{"etiqueta":"CANULA"},{"etiqueta":"CIRCUITOS"},{"etiqueta":"OTROS","valor":"{{insumos_resumen}}"}]},{"tipo":"campos","columnas":1,"campos":[{"etiqueta":"OBSERVACIONES: (Especifique en este campo las observaciones que tenga acerca del estado del equipo en el momento de la entrega)","valor":"{{observaciones}}","arriba":true}]},{"tipo":"pie","texto":"Número de Folios Total: 5"},{"tipo":"salto_pagina"},{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":46}],"ancho_logo":20,"centro":[{"texto":"CONTRATO DE COMODATO\nO\nPRÉSTAMO DE USO","estilo":"titulo"}],"derecha":[{"etiqueta":"","valor":"01 DE MAYO DE 2024"},{"etiqueta":"ELABORADO POR:","valor":"VIERIZ LLANES"},{"etiqueta":"APROBADO POR:","valor":"RODOLFO RODRÍGUEZ"}],"logos_derecha":[{"texto":"{fiduprevisora}"},{"texto":"FOMAG"}],"pie":[{"etiqueta":"COD:","valor":"000"},{"etiqueta":"REVISION:","valor":"00"},{"etiqueta":"VERSION","valor":"01"},{"etiqueta":"Página","valor":"2 de 5"}]},{"tipo":"titulo","texto":"DEVOLUCION DE EQUIPOS"},{"tipo":"campos","columnas":2,"campos":[{"etiqueta":"CIUDAD"},{"etiqueta":"FECHA"}]},{"tipo":"campos","estilo":"tabla","columnas":4,"titulo":"EQUIPOS RECIBIDOS","campos":[{"etiqueta":"EQUIPO:","valor":""},{"etiqueta":"CILINDRO:"},{"etiqueta":"REGULADOR:"},{"etiqueta":"HUMIDIFICADOR"},{"etiqueta":"MARCA:","valor":""},{"etiqueta":"TAMAÑO:","valor":""},{"etiqueta":"MARCA:","valor":""},{"etiqueta":"CANULA"},{"etiqueta":"MODELO:","valor":""},{"etiqueta":"SERIAL:","valor":""},{"etiqueta":"SERIAL:","valor":""},{"etiqueta":"CIRCUITOS"},{"etiqueta":"SERIAL:","valor":"","span":3},{"etiqueta":"OTROS","valor":""}]},{"tipo":"campos","columnas":2,"campos":[{"etiqueta":"QUIEN ENTREGA:"},{"etiqueta":"FIRMA:"},{"etiqueta":"DIRECCION:"},{"etiqueta":"TELEFONO"},{"etiqueta":"NOMBRE DEL PACIENTE QUE RECECIBE EL SERVICIO:","span":2},{"etiqueta":"OBSERVACIONES: (Especifique en este campo las observaciones que tenga acerca del estado del equipo en el momento de la devolución)","span":2,"arriba":true}]},{"tipo":"texto","tamano":11,"texto":"**SEGUNDA. USO AUTORIZADO.** El COMODATARIO podrá usar el bien descrito en el punto anterior, único y exclusivamente en beneficio de la salud y con ocasión del tratamiento recibido por el/la paciente {{paciente_nombre}}, identificado con cedula de ciudadanía N° {{paciente_documento}} de acuerdo con las indicaciones especificadas por los médicos tratantes.\n\n**TERCERA. OBLIGACIONES DEL COMODATARIO.** El COMODATARIO se obliga a:\n**a)** Cuidar, conservar y mantener los bienes o equipos recibidos en comodato, respondiendo por todo daño o deterioro que sufran, salvo aquellos daños que se deriven del deterioro normal por su uso legítimo.\n**b)** Responder por los daños que los bienes entregados causen a terceros.\n**c)** Restituir los bienes al término del comodato en perfecto estado y funcionamiento.\n**d)** Utilizar los bienes conforme con el uso autorizado.\n**e)** No cambiar la ubicación o colocación de los bienes sin el previo y escrito permiso de EL COMODANTE\n**F)** Permitir la revisión, el mantenimiento del equipo.\n**G)** Informar el cambio de domicilio del paciente a FAMILY HOMECARE S.A.S.\n**H)** Restituir los EQUIPOS al vencimiento del contrato que FAMILY HOMECARE S.A.S, tenga celebrado con la EPS; o cuando el paciente se traslade a una EPS O IPS diferente a la de arriba descrita, o a la muerte del paciente, o a la cesación del procedimiento medico por mejoría del paciente.\n**I)** Utilizar los EQUIPOS de acuerdo con el uso autorizado.\n**J)** Dar aviso a FAMILY HOMECARE S.A.S, de cualquier deterioro, o falla que sufran los equipos, especialmente si del mismo se derivan algún riesgo para el funcionamiento correcto del EQUIPO.\n**K)** Informar oportunamente a FAMILY HOMECARE S.A.S del cambio de ubicación ó dirección de los EQUIPOS por cualquier razón."},{"tipo":"pie","texto":"Número de Folios Total: 5"},{"tipo":"salto_pagina"},{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":46}],"ancho_logo":20,"centro":[{"texto":"CONTRATO DE COMODATO\nO\nPRÉSTAMO DE USO","estilo":"titulo"}],"derecha":[{"etiqueta":"","valor":"01 DE MAYO DE 2024"},{"etiqueta":"ELABORADO POR:","valor":"VIERIZ LLANES"},{"etiqueta":"APROBADO POR:","valor":"RODOLFO RODRÍGUEZ"}],"logos_derecha":[{"texto":"{fiduprevisora}"},{"texto":"FOMAG"}],"pie":[{"etiqueta":"COD:","valor":"000"},{"etiqueta":"REVISION:","valor":"00"},{"etiqueta":"VERSION","valor":"01"},{"etiqueta":"Página","valor":"3 de 5"}]},{"tipo":"texto","tamano":11,"texto":"**L)** Responder por el Equipo. LA PERSONA QUE RECIBE o tiene el equipo responderá por el buen uso y trato de los equipos entregados. En el caso de que hubiere de efectuarse cualquier reparación de estos, la mano de obra y los repuestos necesarios para la misma, cuando el daño sea causado por el mal uso o maltrato de los equipos por parte de la persona quien recibe, los costos de la reparación correrán de este último.\n**LL)** No trasladar el equipo o cambiar de domicilio el equipo. Los equipos no podrán ser trasladados por LA PERSONA QUE LO RECIBE ni por terceros al lugar diferente del relacionado, cualquier movilización solo podrá ser efectuada por personal autorizado de FAMILY HOMECARE S.A.S, LA PERSONA QUE RECIBE no podrá cambiar el sitio de ubicación de los equipos sin la debida autorización de FAMILY HOMECARE S.A.S.\n**M)** PAGAR: En caso de pérdida o destrucción total, hurto o cualquier otra situación similar de los equipos, facultara a FAMILY HOMECARE S.A.S, a cobrar a la PERSONA QUE RECIBE el valor de los equipos, según valor comercial de los mismos y quien lo tiene bajo su custodia se obliga a pagarlo.\n**N)** Entregar las órdenes u autorizaciones siguientes que se generen, después de haberse efectuado la entrega de los equipos descritos en las generalidades a FAMILY HOMECARE S.A.S dentro las 24 horas siguientes, debe ser realizada o gestionada por la PERSONA QUE RECIBE o cualquier familiar del paciente ante la EPS o entidad correspondiente.\n**Ñ)** Gestionar: La persona que recibe o beneficiaria del bien, se compromete a gestionar las órdenes siguientes, inmediatamente de haberse vencido dicha orden y tenerla en medio físico.\n**O)** Entregar los Equipos: Los equipos entregados serán retirados por QUIEN ENTREGA si la orden u autorización no se encuentra al día para poder continuar con el USO DEL EQUIPO.\n**P)** Las demás obligaciones propias de los comodatarios de acuerdo con las disposiciones legales.\n\n**CUARTA. Localización de los bienes.** —Los bienes descritos en la cláusula primera deberán permanecer durante la vigencia de este contrato en el domicilio del COMODATARIO, es decir, en la dirección: {{paciente_direccion}}. El COMODATARIO no podrá cambiar el sitio de ubicación de los bienes entregados en comodato sin la previa y escrita autorización del COMODANTE.\n\n**QUINTA: DURACION Y PERFECCIONAMIENTO.** Este contrato tendrá vigencia desde la firma del mismo y durará: A) Hasta tanto la necesidad del paciente lo requiera de acuerdo a los conceptos de los médicos tratantes que establecerán la necesidad del uso del (los) bien (es) objeto del presente contrato B) Hasta la Terminación del contrato de la EPS o entidad correspondiente donde este afiliado el paciente o la que tenga a cargo al paciente a la IPS contratada para la prestación del servicio o al contrario C) Muerte del paciente D) Este contrato tendrá vigencia a partir de la fecha hasta que la FIDUCIARIA LA PREVISORA S.A. VOCERA Y ADMINISTRADORA DE LOS RECURSOS DEL FOMAG, ordene la finalización del servicio. E) Hasta que la FIDUCIARIA LA PREVISORA S.A. VOCERA Y ADMINISTRADORA DE LOS RECURSOS DEL FOMAG, ordene la terminación del acuerdo de voluntades como aceptación a la manifestación de interés para la conformación de la red de proveedores para prestar los servicios y tecnologías en salud para el FOMAG.F) Devolución del equipo por parte el comodatario al comodante.\nParágrafo: Este contrato está sujeto a las prórrogas, circulares, directrices que emita la FIDUCIARIA LA"},{"tipo":"pie","texto":"Número de Folios Total: 5"},{"tipo":"salto_pagina"},{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":46}],"ancho_logo":20,"centro":[{"texto":"CONTRATO DE COMODATO\nO\nPRÉSTAMO DE USO","estilo":"titulo"}],"derecha":[{"etiqueta":"","valor":"01 DE MAYO DE 2024"},{"etiqueta":"ELABORADO POR:","valor":"VIERIZ LLANES"},{"etiqueta":"APROBADO POR:","valor":"RODOLFO RODRÍGUEZ"}],"logos_derecha":[{"texto":"{fiduprevisora}"},{"texto":"FOMAG"}],"pie":[{"etiqueta":"COD:","valor":"000"},{"etiqueta":"REVISION:","valor":"00"},{"etiqueta":"VERSION","valor":"01"},{"etiqueta":"Página","valor":"4 de 5"}]},{"tipo":"texto","tamano":11,"texto":"PREVISORA S.A. **PERFECIONAMIENTO:** El contrato se perfecciona haciendo entrega al COMODANTE de los bienes en el lugar donde deben permanecer o continuando con la prestación del servicio.\n\n**SEXTA. VALOR DE LOS BIENES.** A pesar del ser el COMODATO un préstamo gratuito, entre COMODANTE y COMODATARIO se acuerda que, en caso de pérdida, daño por golpes, no devolución del equipo u otro equivalente, como valor del bien la suma de $5.000.000 PESOS MCTE, más IVA, suma que deberá ser cancelada actualizada al momento del pago del COMODATARIO al COMODANTE. Esta suma la deberá pagar El Comodatario al Comodante en caso de no devolver el equipo. Si **El Comodante** ejerce la facultad que en su favor establece el artículo 2203 del Código Civil, según la cual puede abandonar la propiedad de la cosa en favor de **El Comodatario** cuando los bienes se deterioren de tal manera que no puedan emplearse en su uso ordinario.\n\n**SEXTA. ESTADO DE LOS BIENES.** Al momento en que se firma el presente contrato, se entrega materialmente el bien (o bienes), se deja constancia por ambas partes que el mismo se encuentra en perfecto estado para su uso.\n\n**SEPTIMA.** Restitución o terminación del contrato. - El comodatario deberá restituir el mueble, elementos o equipo entregado en calidad de préstamo de uso, en los siguientes casos: 1) Cuando el tratamiento establece un término, es decir; al Vencimiento del mismo; 2) por el incumplimiento de las obligaciones del comodatario en relación con la destinación, la utilización inadecuada, o el deterioro del equipo por su culpa. 3) por muerte de la persona comodataria; 4) Por la terminación de los servicios a los que se destinó el mueble. 5) Por la terminación o suspensión de la continuidad de la prestación del servicio en salud de parte FIDUCIARIA LA PREVISORA S.A. VOCERA Y ADMINISTRADORA DE LOS RECURSOS DEL FOMAG.\n\n**OCTAVA.** Cesión. - Queda prohibida la cesión del contrato a cualquier persona natural o jurídica.\n\n**NOVENA. INDEMNIZACIÓN POR INCUMPLIMIENTO.** El incumplimiento por parte del **COMODATARIO** de alguna o algunas de las obligaciones derivadas del presente contrato, especialmente la no restitución de los bienes dará derecho a **LAS COMODANTES** para exigir inmediatamente, a título de pena, una suma de dinero diaria equivalente a **CINCO SALARIOS MÍNIMOS MENSUALES LEGALES VIGENTES**. Por el pago de la pena no se extingue la obligación principal de restituir el o los equipos entregados, la cual podrá ser exigida separadamente, con indemnización de perjuicios.\n\n**DECIMA. MÉRITO EJECUTIVO.** Las partes, reconocen que el presente documento presta mérito ejecutivo para la exigencia judicial del cumplimiento de las obligaciones en él contenidas.\n\n**DECIMA PRIMERA. CLAUSULA COMPROMISORIA.** Toda controversia o diferencia relativa a este contrato, su ejecución y cumplimiento, se resolverá inicialmente mediante la conciliación y la amigable composición conforme a la normatividad vigente sobre sistemas alternos de solución de conflictos y demás normas"},{"tipo":"pie","texto":"Número de Folios Total: 5"},{"tipo":"salto_pagina"},{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":46}],"ancho_logo":20,"centro":[{"texto":"CONTRATO DE COMODATO\nO\nPRÉSTAMO DE USO","estilo":"titulo"}],"derecha":[{"etiqueta":"","valor":"01 DE MAYO DE 2024"},{"etiqueta":"ELABORADO POR:","valor":"VIERIZ LLANES"},{"etiqueta":"APROBADO POR:","valor":"RODOLFO RODRÍGUEZ"}],"logos_derecha":[{"texto":"{fiduprevisora}"},{"texto":"FOMAG"}],"pie":[{"etiqueta":"COD:","valor":"000"},{"etiqueta":"REVISION:","valor":"00"},{"etiqueta":"VERSION","valor":"01"},{"etiqueta":"Página","valor":"5 de 5"}]},{"tipo":"texto","tamano":11,"texto":"concordantes."},{"tipo":"espacio","alto":60},{"tipo":"firmas","firmas":[{"rol":"vacia","titulo":"COMODANTE","lineas":[{"etiqueta":"C.C.","valor":"77.091.109"},{"etiqueta":"CELULAR:","valor":"3156719559"},{"etiqueta":"Correo electrónico:","valor":"shorbogh@hotmail.com"}]},{"rol":"recibe","titulo":"COMODATARIO","lineas":[{"etiqueta":"C.C.","valor":"{{recibe_documento}}"},{"etiqueta":"CELULAR:","valor":"{{recibe_telefono}}"},{"etiqueta":"Correo electrónico:","valor":"{{recibe_correo}}"}]}]},{"tipo":"pie","texto":"Número de Folios Total: 5"}]$bloques$::jsonb,
  'prestamo', 'entrega', false, false, true
WHERE NOT EXISTS (SELECT 1 FROM plantillas_acta WHERE nombre = 'Family Homecare / FOMAG — Contrato de comodato');

