INSERT INTO plantillas_acta (nombre, descripcion, bloques, accion, tipo, es_estandar, uso_general, activo)
SELECT 'Acta de cambio de equipo Family', 'Cambio de equipos médicos domiciliarios de Family Homecare / FOMAG: el que se retira y el que se entrega.', $bloques$[{"tipo":"encabezado","logos":[{"url":"https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/clientes/family-homecare.jpg","alto":62}],"ancho_logo":28,"centro":[{"texto":"ACTA GENERAL DE EQUIPOS MEDICOS DOMICILIARIOS O SUMINISTRO OXIGENO DOMICILIARIO","estilo":"titulo"}]},{"tipo":"titulo","texto":"CAMBIO DE EQUIPOS"},{"tipo":"campos","columnas":3,"campos":[{"etiqueta":"CIUDAD","valor":"{{ciudad}}"},{"etiqueta":"FECHA","valor":"{{fecha}}"},{"etiqueta":"HORA","valor":"{{hora}}"}]},{"tipo":"tabla","fuente":"retirados","agrupar":"tipo","titulo":"EQUIPOS QUE SE RETIRAN"},{"tipo":"tabla","fuente":"equipos","agrupar":"tipo","titulo":"EQUIPOS QUE SE ENTREGAN"},{"tipo":"campos","columnas":3,"campos":[{"etiqueta":"MOTIVO DEL CAMBIO:","valor":"{{motivo_cambio}}","span":3},{"etiqueta":"QUIEN ENTREGA:","valor":"{{entrega_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"entrega"},{"etiqueta":"QUIEN RECIBE:","valor":"{{recibe_nombre}}","span":2},{"etiqueta":"FIRMA:","firma":"recibe"},{"etiqueta":"DIRECCION:","valor":"{{paciente_direccion}}","span":2},{"etiqueta":"TELEFONO","valor":"{{recibe_telefono}}"},{"etiqueta":"NOMBRE DEL PACIENTE:","valor":"{{paciente_nombre}}","span":3},{"etiqueta":"OBSERVACIONES: ( Especifique en este campo las observaciones que tenga acerca del estado del equipo en el momento del cambio)","valor":"{{observaciones}}","span":3,"arriba":true}]},{"tipo":"texto","tamano":11,"texto":"Por medio de la presente acta se hace constar el cambio de los equipos biomedicos y/o suministros de oxigeno domiciliario descritos, entregados en calidad de prestamo. Los equipos que se retiran quedan bajo la custodia de FAMILY HOMECARE S.A.S; la custodia y buen uso de los equipos entregados son responsabilidad del paciente o familiar a partir de la fecha de este cambio."}]$bloques$::jsonb,
  'cambio', 'entrega', false, false, true
WHERE NOT EXISTS (SELECT 1 FROM plantillas_acta WHERE nombre = 'Acta de cambio de equipo Family');

-- 2) Asignarlas a FOMAG y FAMILY HOMECARE SAS (el orden es el de las pestañas al llenar)
INSERT INTO cliente_plantillas_acta (cliente_id, plantilla_id, orden)
SELECT c.id, p.id, n.orden
FROM (VALUES ('Family Homecare / FOMAG — Contrato de comodato', 0), ('Family Homecare / FOMAG — Entrega CPAP - BPAP (F-FAM-11)', 1), ('Family Homecare / FOMAG — Entrega Oxígeno (F-FAM-11)', 2), ('Family Homecare / FOMAG — Entrega Otros equipos (F-FAM-11)', 3), ('Acta de cambio de equipo Family', 4)) AS n(nombre, orden)
JOIN plantillas_acta p ON p.nombre = n.nombre
JOIN clientes c ON c.nombre IN ('FOMAG', 'FAMILY HOMECARE SAS')
ON CONFLICT (cliente_id, plantilla_id) DO NOTHING;

-- 3) Desactivar la plantilla vieja y quitarla de los clientes
DELETE FROM cliente_plantillas_acta WHERE plantilla_id IN (SELECT id FROM plantillas_acta WHERE nombre = 'Family Homecare / FOMAG — Comodato, acta general y F-FAM-11');
UPDATE plantillas_acta SET activo = false WHERE nombre = 'Family Homecare / FOMAG — Comodato, acta general y F-FAM-11';

COMMIT;

-- Verificación: deben salir las 5 nuevas activas, cada una con FOMAG y FAMILY HOMECARE SAS,
-- y la vieja con activo = false y sin clientes
SELECT p.nombre, p.accion, p.activo, string_agg(c.nombre || ' (' || cp.orden || ')', ', ' ORDER BY c.nombre) AS clientes
FROM plantillas_acta p
LEFT JOIN cliente_plantillas_acta cp ON cp.plantilla_id = p.id
LEFT JOIN clientes c ON c.id = cp.cliente_id
WHERE p.nombre ILIKE '%family%'
GROUP BY p.nombre, p.accion, p.activo
ORDER BY p.activo DESC, p.nombre;
